def objs(f, colors='RrbNY'):
    out=[]
    for n in f.segmentation['nodes']:
        if n['color'] in colors:
            b=n['boundary']
            out.append(f"{n['color']}{n['pixels']}@({b[0][0]},{b[0][1]})")
    return ' '.join(out)
