def colmap(f):
    g = f.ascii.split('\n')
    m = {}
    for r,row in enumerate(g):
        for c,ch in enumerate(row):
            m.setdefault(ch, set()).add((r,c))
    return m
def setdiff_info(before, after, colors):
    for ch in colors:
        b = before.get(ch,set()); a = after.get(ch,set())
        add = a-b; rem = b-a
        if not add and not rem: continue
        def rng(s):
            rs=[p[0] for p in s]; cs=[p[1] for p in s]
            return (min(rs),max(rs),min(cs),max(cs)) if s else None
        print(f' {ch}: n {len(b)}->{len(a)} removed={len(rem)} {rng(rem)} added={len(add)} {rng(add)}')
