def state():
    L = current_frame.ascii.split('\n')
    out={}
    for col in ['B','c','Y','S']:
        s = cells(col, L)
        if col=='Y': s -= set((r,63) for r in range(64))
        if col=='S': out['mirror']=(min(c for _,c in s), max(c for _,c in s))
        elif col=='c': out['charcoal']=sorted(s)[:1] and (min(r for r,_ in s),max(r for r,_ in s),min(c for _,c in s),max(c for _,c in s))
        elif col=='B': out['black']=(min(r for r,_ in s),max(r for r,_ in s),min(c for _,c in s),max(c for _,c in s))
        else: out['targetY']=(min(r for r,_ in s),max(r for r,_ in s),min(c for _,c in s),max(c for _,c in s))
    # budget bar = count of Y in col 63
    out['budget']=sum(1 for r in range(64) if L[r][63]=='Y')
    return out
