import collections
def comps(cells):
    seen=set(); out=[]
    for s in cells:
        if s in seen: continue
        q=[s]; seen.add(s); grp=[]
        while q:
            u=q.pop(); grp.append(u)
            for d in ((1,0),(-1,0),(0,1),(0,-1)):
                v=(u[0]+d[0],u[1]+d[1])
                if v in cells and v not in seen: seen.add(v); q.append(v)
        out.append(sorted(grp))
    return out
