def sboxes(G):
    boxes=[]
    seen=set()
    for r in range(64):
        for c in range(64):
            if G[r][c]=='S' and (r,c) not in seen:
                # flood
                import collections
                q=collections.deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        if 0<=x+dx<64 and 0<=y+dy<64 and G[x+dy+0][x*0+y+dy] if False else False: pass
                boxes.append(cells)
    return boxes
