def click(r,c):
    before=current_frame
    res=action([{'action':'MOUSE','row':r,'col':c}])
    d=frame_diff(before,current_frame)
    print(f'({r},{c}) no_op={res["no_op"]} chg={d["changed_cell_count"]} lvl_done={res["level_completed"]} over={res["game_over"]}')
    print('   before bars:', {k:v[0] for k,v in bars(before).items()}, ' after:', {k:v[0] for k,v in bars(current_frame).items()})
    for k in ('moved','rotated','appeared','disappeared','changed_color'):
        if d.get(k): print('   ',k,d[k][:4])
    return res
