def bars(fr=None):
    fr = fr or current_frame
    s = fr.segmentation
    out = {}
    for n in s['nodes']:
        if n['color'] in ('N','Y') and n['pixels']>=3 and (n['boundary'][0][0]<15 or 25<n['boundary'][0][0]<36):
            b = n['boundary']
            r0=min(p[0] for p in b); r1=max(p[0] for p in b); c0=min(p[1] for p in b); c1=max(p[1] for p in b)
            out[n['color']] = (r0,r1,c0,c1,n['pixels'])
    for n in s['nodes']:
        if n['color']=='r' and n['pixels']==1:
            p=n['boundary'][0]
            if p[0]<20 and p[1]<40: out['dotG']=p
            if 20<p[0]<40 and p[1]<20: out['dotY']=p
    return out
